                extra.ttfb_ms = Math.max(0, entry.responseStart - entry.requestStart);
                extra.network_body_ms = Math.max(0, entry.responseEnd - entry.responseStart);
                extra.after_network_ms = Math.max(0, finished - entry.responseEnd);
