    if (action === 'fs.read') return '读取 ' + pattern;
    if (action === 'fs.write') return '写入 ' + pattern;
    if (action === 'fs.delete') return '删除 ' + pattern;
    if (action === 'network.connect') return '网络 ' + pattern;
    if (action === 'web.search') return '联网搜索 ' + pattern;
